const req = $input.first().json || {};
const raw = req.body && req.body.payload;
const payload = JSON.parse(raw);
// Slack re-sends the same interaction when it gets no 200 within 3 seconds (cold start). The first run keeps going,
// so a retry must be acknowledged and dropped, never processed twice (double send, double post).
const hdr = req.headers || {};
const retryNum = hdr['x-slack-retry-num'] || hdr['X-Slack-Retry-Num'] || null;
const is_retry = retryNum !== null && retryNum !== undefined && String(retryNum) !== '' && String(retryNum) !== '0';
let action_id = null;
let action_type = payload.type || null;
let action_value = null;
let channel_id = (payload.channel && payload.channel.id) || null;
let thread_ts = null;
let message_ts = null;
if (payload.type === 'view_submission') {
  const view = payload.view || {};
  action_id = view.callback_id || null;
  action_value = view.state || null;
  // Modals opened by this wizard carry the thread context in private_metadata (JSON)
  let meta = null;
  try { meta = JSON.parse(view.private_metadata || ''); } catch (e) { meta = null; }
  if (meta && typeof meta === 'object') {
    channel_id = channel_id || meta.channel_id || null;
    thread_ts = meta.thread_ts || null;
    message_ts = meta.message_ts || null;
  } else {
    channel_id = channel_id || (view.private_metadata || null);
  }
} else {
  const act = (payload.actions && payload.actions[0]) || {};
  action_id = act.action_id || null;
  if (Array.isArray(act.selected_options)) {
    action_value = act.selected_options.map(o => o.value);
  } else {
    action_value = (act.selected_option && act.selected_option.value) || act.value || null;
  }
  const msg = payload.message || {};
  thread_ts = msg.thread_ts || msg.ts || null;
  message_ts = msg.ts || null;
}
const threadKey = thread_ts || message_ts || null;
const session_key = channel_id && threadKey ? channel_id + '_' + threadKey : null;
return [{ json: {
  action_id,
  action_type,
  action_value,
  is_retry,
  retry_reason: hdr['x-slack-retry-reason'] || hdr['X-Slack-Retry-Reason'] || null,
  trigger_id: payload.trigger_id || null,
  user_id: (payload.user && payload.user.id) || null,
  user_name: (payload.user && payload.user.username) || null,
  channel_id,
  thread_ts,
  message_ts,
  session_key,
  response_url: payload.response_url || null,
  full_payload: payload
} }];

function getSessionRow() {
  var items = $('Load Session').all();
  if (!items.length) return null;
  var r = items[0].json || {};
  return r.session_key ? r : null;
}
var TTL_MS = 30 * 60 * 1000;
function isFresh(row) {
  return !!(row && row.updated_at && (Date.now() - Date.parse(row.updated_at) <= TTL_MS));
}

const WIZARD_STEPS = ['audience_select', 'filters', 'sample_size', 'review_candidates', 'review_email', 'sending', 'complete'];

const p = $input.first().json;
const actionId = p.action_id || '';
const isUxr = typeof actionId === 'string' && actionId.startsWith('uxr_');

const row = getSessionRow();
const fresh = isFresh(row);

let sessionExpired = false;
if (isUxr && p.session_key && !actionId.startsWith('uxr_audience_') && !actionId.startsWith('uxr_cancel') && !fresh) {
  sessionExpired = true;
}

let sessionState = null;
if (fresh) {
  let filters = {};
  try { filters = JSON.parse(row.filters_json || '{}'); } catch (e) { filters = {}; }
  sessionState = {
    step: row.state,
    audience_type: row.audience || null,
    filters: filters,
    sample_size: row.requested_count || null,
    batch_id: row.batch_id || null,
    calendly_link: row.calendly_link || null,
    email_subject: row.email_subject || null,
    email_body: row.email_body || null
  };
}

return [{ json: {
  ...p,
  is_uxr: isUxr,
  session_expired: sessionExpired,
  session_state: sessionState,
  wizard_steps: WIZARD_STEPS
} }];

const AUDIENCE_LABELS = { n8n_users: 'n8n users', volunteers: 'Research volunteers', non_users: 'Non-users' };
function audienceLabel(a) { return AUDIENCE_LABELS[a] || a || 'unknown'; }
function defsFor(config, audience) {
  if (audience === 'n8n_users') return config.nUserFilters || [];
  return config.volunteerFilters || config.nonUserFilters || [];
}
function optionText(o) { return { type: 'plain_text', text: String(o.label || o.value).slice(0, 75), emoji: true }; }
function renderFilterBlocks(config, audience, filters) {
  const defs = defsFor(config, audience);
  const blocks = [
    { type: 'section', text: { type: 'mrkdwn', text: ':busts_in_silhouette: *Audience: ' + audienceLabel(audience) + '*\n\nSelect any filters you want to apply (you can pick more than one value per filter). All are optional. The % tells you how many profiles carry that information.' } },
    { type: 'divider' }
  ];
  const disabled = [];
  for (const def of defs) {
    if (def.enabled === false) { disabled.push(def); continue; }
    const options = (def.options || []).map(o => ({ text: optionText(o), value: String(o.value) }));
    const hasKey = filters && Object.prototype.hasOwnProperty.call(filters, def.id);
    const raw = hasKey ? filters[def.id] : (def.default || []);
    const selected = (Array.isArray(raw) ? raw : (raw ? [raw] : [])).map(String);
    const selectedOptions = options.filter(o => selected.includes(o.value));
    const labelsOf = selectedOptions.map(o => o.text.text);
    let selectedLine;
    if (!hasKey && def.default && def.default.length) selectedLine = '*Selected (default):* ' + labelsOf.join(', ');
    else if (labelsOf.length) selectedLine = '*Selected:* ' + labelsOf.join(', ');
    else selectedLine = '_Selected: none' + (def.default && def.default.length ? ' (default applies)' : '') + '_';
    let text = '*' + def.label + '*  ·  _available in ' + (def.coverage || '?') + ' of profiles' + (def.coverageNote ? ', ' + def.coverageNote : '') + '_';
    if (def.hint) text += '\n' + def.hint;
    text += '\n' + selectedLine;
    const element = { type: 'multi_static_select', action_id: 'uxr_filter_' + def.id, placeholder: { type: 'plain_text', text: 'Select one or more' }, options };
    if (selectedOptions.length) element.initial_options = selectedOptions;
    blocks.push({ type: 'section', block_id: 'filter_' + def.id, text: { type: 'mrkdwn', text }, accessory: element });
  }
  if (disabled.length) {
    blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: ':hourglass_flowing_sand: *Coming soon* (needs Customer.io segments): ' + disabled.map(d => d.label).join(', ') + '  ·  _available in ' + (disabled[0].coverage || '~10%') + ' of profiles' + (disabled[0].coverageNote ? ', ' + disabled[0].coverageNote : '') + '_' }] });
  }
  blocks.push({ type: 'divider' });
  blocks.push({ type: 'actions', elements: [
    { type: 'button', text: { type: 'plain_text', text: ':white_check_mark: Apply Filters', emoji: true }, style: 'primary', action_id: 'uxr_filter_apply', value: 'apply' },
    { type: 'button', text: { type: 'plain_text', text: 'Cancel', emoji: true }, action_id: 'uxr_cancel', value: 'cancel' }
  ] });
  return blocks;
}
function filterSummaryLines(config, audience, filters) {
  const defs = defsFor(config, audience);
  const lines = [];
  for (const def of defs) {
    if (def.enabled === false) continue;
    const hasKey = filters && Object.prototype.hasOwnProperty.call(filters, def.id);
    const raw = hasKey ? filters[def.id] : null;
    const vals = (Array.isArray(raw) ? raw : (raw ? [raw] : [])).map(String);
    if (vals.length) {
      const labels = vals.map(v => { const o = (def.options || []).find(x => String(x.value) === v); return o ? (o.label || o.value) : v; });
      lines.push('• *' + def.label + '*: ' + labels.join(', '));
    } else if (def.default && def.default.length) {
      lines.push('• *' + def.label + '*: _default (everyone except deleted accounts)_');
    }
  }
  return lines;
}

const parsed = $('Parse Payload').first().json;
const config = $input.first().json || {};
const audienceType = parsed.action_value;
const nowIso = new Date().toISOString();
const blocks = renderFilterBlocks(config, audienceType, {});
return [{ json: {
