function getSessionRow() {
  var items = $('Load Session').all();
  if (!items.length) return null;
  var r = items[0].json || {};
  return r.session_key ? r : null;
}
const parsed = $('Parse Payload').first().json;
const config = $input.first().json || {};
const row = getSessionRow();
const nowIso = new Date().toISOString();
if (!row) return [{ json: { skip: true, post_message: false, update_message: false, sess: { session_key: '__none__', state: '', filters_json: '{}', updated_at: nowIso } } }];

let filters = {};
try { filters = JSON.parse(row.filters_json || '{}'); } catch (e) { filters = {}; }
const actionId = parsed.action_id;

if (actionId === 'uxr_filter_apply' || actionId === 'uxr_filter_skip') {
  const maxSample = Number(config.maxSampleSize) || 20;
  const lines = filterSummaryLines(config, row.audience, filters);
  const filterSummary = lines.length ? lines.join('\n') : '_No filters applied. Sampling from the full pool._';
  const blocks = [
    { type: 'section', text: { type: 'mrkdwn', text: ':1234: *How many people do you want to contact?*\n\n*Audience:* ' + audienceLabel(row.audience) + '\n*Filters:*\n' + filterSummary } },
    { type: 'input', block_id: 'sample_size_block', element: { type: 'number_input', is_decimal_allowed: false, action_id: 'uxr_sample_size_input', min_value: '1', max_value: String(maxSample), placeholder: { type: 'plain_text', text: 'e.g. 10' } }, label: { type: 'plain_text', text: 'Number of people to contact (1-' + maxSample + ')' } },
    { type: 'actions', elements: [ { type: 'button', text: { type: 'plain_text', text: ':white_check_mark: Draw Sample', emoji: true }, style: 'primary', action_id: 'uxr_sample_draw', value: 'draw' }, { type: 'button', text: { type: 'plain_text', text: 'Cancel', emoji: true }, action_id: 'uxr_cancel', value: 'cancel' } ] }
  ];
  return [{ json: { channel_id: parsed.channel_id, thread_ts: parsed.thread_ts, text: 'How many people do you want to contact?', blocks: JSON.stringify(blocks), post_message: true, update_message: false, sess: { session_key: row.session_key, state: 'sample_size', filters_json: JSON.stringify(filters), updated_at: nowIso } } }];
}

// A dropdown changed: store it and refresh the filters message so the selection is visible
const filterId = actionId.replace('uxr_filter_', '');
const v = parsed.action_value;
filters[filterId] = Array.isArray(v) ? v : (v ? [v] : []);
const blocks = renderFilterBlocks(config, row.audience, filters);
return [{ json: { skip: false, stored_filter: filterId, value: filters[filterId], post_message: false, update_message: !!parsed.message_ts, channel_id: parsed.channel_id, message_ts: parsed.message_ts, blocks: JSON.stringify(blocks), sess: { session_key: row.session_key, state: row.state, filters_json: JSON.stringify(filters), updated_at: nowIso } } }];

// Slack may expand emails/URLs in interaction payloads. Recheck the actual text before every update.
function safeSlackBlocks(blocks) {
  const result = [];
  for (const block of blocks) {
    if (block.type !== 'section' || !block.text || block.text.text.length <= 3000) { result.push(block); continue; }
    let remaining = block.text.text;
    const pieces = [];
    while (remaining.length > 3000) {
      let end = remaining.lastIndexOf('\n', 2999) + 1;
      if (!end) end = remaining.lastIndexOf(' ', 2999) + 1;
      if (!end) end = 3000;
      const open = remaining.lastIndexOf('<', end - 1);
      if (open >= 0 && remaining.indexOf('>', open) >= end) {
        if (open === 0) throw new Error('A single Slack link exceeds 3000 characters.');
        end = open;
      }
      if (/[\uD800-\uDBFF]/.test(remaining[end - 1])) end--;
      pieces.push(remaining.slice(0, end));
      remaining = remaining.slice(end);
    }
    if (remaining) pieces.push(remaining);
    pieces.forEach((text, i) => {
      const part = {...block, expand: true, text: {...block.text, text}};
      delete part.block_id;
      if (i) { delete part.fields; delete part.accessory; }
      result.push(part);
    });
  }
  if (result.length > 50) throw new Error('This Slack message exceeds 50 blocks. Reduce the sample size.');
  return result;
