const prep = $('Prepare Search').first().json;
const result = $input.first().json || {};
const nowIso = new Date().toISOString();

const expiredBlocks = [{ type: 'section', text: { type: 'mrkdwn', text: ':hourglass: This recruiting session is no longer active. Please start a new one by asking Darwin to recruit participants.' } }];
if (prep.skip) return [{ json: { channel_id: prep.channel_id, thread_ts: prep.thread_ts, text: 'Session no longer active.', blocks: JSON.stringify(expiredBlocks), candidates: [], batch_id: '', sess: { session_key: '__none__', state: '', requested_count: 0, batch_id: '', updated_at: nowIso } } }];

