  : (filterEntries.length ? displayText(filterEntries.map(([k,v]) => k + '=' + (Array.isArray(v) ? v.join('|') : v)).join(', ')) : (prep.mode === 'n8n_users' ? 'none (everyone except deleted accounts)' : 'none'));

const cancelBtn = { type: 'button', text: { type: 'plain_text', text: 'Cancel', emoji: true }, action_id: 'uxr_cancel', value: 'cancel' };
