const errText = result.error || prep.csv_error || (result.message && !Array.isArray(result.candidates) ? result.message : null);
if (errText) {
  const blocks = [
    { type: 'section', text: { type: 'mrkdwn', text: ':x: *Search failed*\n\n*Audience:* ' + audienceLabel + '\n*Filters:* ' + filterSummary + '\n\n```' + String(errText).slice(0, 600) + '```\nTry *New Sample*, or cancel and start over.' } },
