}

const found = Array.isArray(result.candidates) ? result.candidates : [];
const batchId = found.length ? ('batch_' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 8)) : '';

function normalizeLinkedin(v) {
  if (!v) return null;
  let u = String(v).trim();
  if (!u || u.length < 8) return null;
  if (!/^https?:\/\//i.test(u)) u = 'https://' + u;
  return /linkedin\.com/i.test(u) ? u : null;
}

function summarize(c) {
  const parts = [];
  if (prep.mode === 'n8n_users' || (prep.mode === 'csv' && c.cloud_plan)) {
    if (c.cloud_plan) parts.push(c.cloud_plan + (c.cloud_plan_status ? ' (' + c.cloud_plan_status + ')' : ''));
    if (c.role) parts.push(c.role);
    if (c.company_size) parts.push(c.company_size);
    if (c.usage_summary) parts.push(c.usage_summary);
  } else {
    const USAGE = { active: 'active user', occasional: 'occasional user', explorer: 'explorer', aware: 'aware, never used', new: 'never heard of n8n' };
    const SKILLS = { tech_high: 'high-tech', tech_mid: 'mid-tech', tech_low: 'low-tech', tech_none: 'non-tech' };
    if (c.n8n_usage) parts.push(USAGE[c.n8n_usage] || c.n8n_usage);
    if (c.tech_skills) parts.push(SKILLS[c.tech_skills] || c.tech_skills);
    if (c.work_role) parts.push(String(c.work_role).slice(0, 40));
    if (c.country) parts.push(c.country);
    if (c.company_size) parts.push(c.company_size);
  }
  return parts.length ? parts.join(' · ') : (c.attributes_fetched === false ? 'profile details unavailable' : 'no profile details');
}

const candidates = found.map(c => ({
  email: c.email || '',
  first_name: c.first_name || '',
  cio_id: c.cio_id || c.id || '',
  n8n_usage: c.n8n_usage || null,
  tech_skills: c.tech_skills || null,
  work_role: c.work_role || null,
  attributes_fetched: c.attributes_fetched !== false,
  cloud_plan: c.cloud_plan || null,
  cloud_plan_status: c.cloud_plan_status || null,
  role: c.role || null,
  country: c.country || null,
  company_size: c.company_size || null,
  usage_summary: c.usage_summary || '',
  linkedin: normalizeLinkedin(c.linkedin),
  cio_url: (c.cio_url && /^https:\/\/fly\.customer\.io\//.test(String(c.cio_url))) ? String(c.cio_url) : null,
  summary: summarize(c)
}));

const pool = Number(result.totalMatchingEstimate) || 0;
const poolText = pool > 0 ? ((result.poolIsExact ? '' : '~') + pool.toLocaleString('en-US') + ' people match' + (result.poolIsExact ? '' : ' (estimate)')) : 'pool size unknown';
const effectiveSize = Number(result.requestedSize) || prep.sampleSize;
const cappedNote = effectiveSize < prep.sampleSize ? ('\n:information_source: _Asked for ' + prep.sampleSize + ', capped at ' + effectiveSize + ' (maxSampleSize in UXR Config)._') : '';
const shortfall = candidates.length < effectiveSize ? ('\n:warning: _Asked for ' + effectiveSize + ', found ' + candidates.length + '. The pool for these filters is small.' + '_') : '';
const cooldownNote = result.cooldownDropped ? ('\n_' + result.cooldownDropped + ' recently-invited profile(s) skipped (cooldown)._') : '';
const dupNote = result.duplicateEmailsDropped ? ('\n_' + result.duplicateEmailsDropped + ' duplicate profile(s) with the same email collapsed: one email = one invite._') : '';
const cs = result.csvStats;
const csvNote = cs ? ('\n*CSV:* ' + cs.total + ' unique email addresses uploaded · ' + candidates.length + ' selected.\nNo invitations have been sent yet.') : '';
const csvBlocks = [];
if (cs) {
  const duplicates = Array.isArray(cs.duplicateProfileEmails) ? cs.duplicateProfileEmails : [];
  const conflicts = Array.isArray(cs.unsubscribeConflictEmails) ? cs.unsubscribeConflictEmails : [];
  if (conflicts.length) csvBlocks.push({ type: 'section', text: { type: 'mrkdwn', text:
    ':warning: *Different unsubscribe statuses for ' + conflicts.length + ' email address' + (conflicts.length === 1 ? '' : 'es') + '*\n' +
    'Some checked profiles were excluded as unsubscribed while another profile with the same email passed that check. This does not establish permission to contact that address. Review the flagged addresses before approving.' } });
}
const duplicateCounts = new Map((cs && Array.isArray(cs.duplicateProfileEmails) ? cs.duplicateProfileEmails : []).map(r => [r.email, r.profileCount]));
const conflictAddresses = new Set(cs && Array.isArray(cs.unsubscribeConflictEmails) ? cs.unsubscribeConflictEmails : []);
