function buildPreviewBlocks(subject, body, count, note, options, selectedUrl) {
  const opts = parseOptions(options).slice(0, 99);
  const blocks = [
    { type: 'section', text: { type: 'mrkdwn', text: ':email: *Email Preview*\n\nThis email will be sent to *' + count + ' people*. Review and approve, or edit before sending.' + (note || '') } },
