  ];
  const link = selectedUrl ? String(selectedUrl) : '';
  const matchIdx = link && link !== 'custom' ? opts.findIndex(o => stripQuery(o.url) === stripQuery(link)) : -1;
  const customChosen = link === 'custom' || (!!link && matchIdx < 0);
  const customInitial = (customChosen && link !== 'custom') ? link : '';
  if (opts.length) {
    const slackOpts = opts.map((o, i) => ({ text: { type: 'plain_text', text: String(o.label || o.url).slice(0, 75) }, value: 'opt_' + i }));
    slackOpts.push({ text: { type: 'plain_text', text: 'Custom URL' }, value: 'custom' });
    const el = { type: 'static_select', action_id: 'uxr_email_calendly_select', placeholder: { type: 'plain_text', text: 'Choose your Calendly event' }, options: slackOpts };
    if (matchIdx >= 0) el.initial_option = slackOpts[matchIdx];
    else if (customChosen) el.initial_option = slackOpts[slackOpts.length - 1];
    blocks.push({ type: 'input', block_id: 'calendly_block', optional: false, element: el, label: { type: 'plain_text', text: 'Booking link' } });
    if (customChosen) {
      const input = { type: 'url_text_input', action_id: 'uxr_email_calendly_url', placeholder: { type: 'plain_text', text: 'https://calendly.com/...' } };
      if (customInitial) input.initial_value = customInitial;
      blocks.push({ type: 'input', block_id: 'calendly_custom_block', optional: true, element: input, label: { type: 'plain_text', text: 'Custom booking URL' } });
    }
  } else {
    const input = { type: 'url_text_input', action_id: 'uxr_email_calendly_url', placeholder: { type: 'plain_text', text: 'https://calendly.com/your-link' } };
    if (customInitial) input.initial_value = customInitial;
    blocks.push({ type: 'input', block_id: 'calendly_custom_block', element: input, label: { type: 'plain_text', text: 'Your Calendly booking URL' } });
  }
  blocks.push({ type: 'actions', elements: [ { type: 'button', text: { type: 'plain_text', text: ':white_check_mark: Approve & Send' + ($('Load Config (Email)').first().json.liveMode === true ? '' : ' (TEST MODE)'), emoji: true }, style: 'primary', action_id: 'uxr_send_approve', value: 'send' }, { type: 'button', text: { type: 'plain_text', text: ':pencil: Edit Email', emoji: true }, action_id: 'uxr_email_edit', value: 'edit' }, { type: 'button', text: { type: 'plain_text', text: 'Cancel', emoji: true }, action_id: 'uxr_cancel', value: 'cancel' } ] });
