const emailRe = /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g;
let emails = [];
if (lines.length) {
  const sep = (lines[0].match(/;/g) || []).length > (lines[0].match(/,/g) || []).length ? ';' : (lines[0].indexOf('\t') !== -1 ? '\t' : ',');
  const header = lines[0].split(sep).map(h => h.replace(/^"|"$/g, '').trim().toLowerCase());
