// Slack may expand emails/URLs in interaction payloads. Recheck the actual text before every update.
function safeSlackBlocks(blocks) {
  const result = [];
  for (const block of blocks) {
    if (block.type !== 'section' || !block.text || block.text.text.length <= 3000) { result.push(block); continue; }
    let remaining = block.text.text;
    const pieces = [];
    while (remaining.length > 3000) {
      let end = remaining.lastIndexOf('\n', 2999) + 1;
      if (!end) end = remaining.lastIndexOf(' ', 2999) + 1;
      if (!end) end = 3000;
      const open = remaining.lastIndexOf('<', end - 1);
      if (open >= 0 && remaining.indexOf('>', open) >= end) {
        if (open === 0) throw new Error('A single Slack link exceeds 3000 characters.');
        end = open;
      }
      if (/[\uD800-\uDBFF]/.test(remaining[end - 1])) end--;
      pieces.push(remaining.slice(0, end));
      remaining = remaining.slice(end);
    }
    if (remaining) pieces.push(remaining);
    pieces.forEach((text, i) => {
      const part = {...block, expand: true, text: {...block.text, text}};
      delete part.block_id;
      if (i) { delete part.fields; delete part.accessory; }
      result.push(part);
    });
  }
  if (result.length > 50) throw new Error('This Slack message exceeds 50 blocks. Reduce the sample size.');
  return result;
}
